options=read('/input/options')
ids=[]
for o in options:
 if 'alpha' in o['tags'] and 'beta' in o['tags']:
  ids=[o['id']]
  break
if not ids:
 for o in options:
  if 'alpha' in o['tags']:
   for p in options:
    if 'beta' in p['tags']:
     ids=[o['id'],p['id']]
     break
   if ids:
    break
if not ids:
  ids=[options[0]['id']]
result=ids

